// spec: specs/business-cards-images.md (2.1, 2.2) · кейсы: .qa/tests/business-cards-images/CARDIMG-08, CARDIMG-09
// #494e0b (тикет 96, PR #217): картинка карточки ….card3.webp — однотонные поля обрезаны при подготовке файла;
// окно 4:3 с object-fit contain (#0a2499) остаётся. seed: tests/seed.spec.ts (гость) · прод, только просмотр:
// не-GET блокируются (prepare из cards.helpers), cookie «חיוניים בלבד» и PWA-снуз заранее, SW выключен.
// Замер полос — canvas (trim.helpers.ts): fetch(currentSrc) → createImageBitmap → яркость по строкам/столбцам.
import { test, expect, Page, Locator } from '@playwright/test';
import { prepare, MEDIA } from './cards.helpers';
import { COOKIE_PWA_INIT, darkEdges, measureLines, short, uniformMargins } from './trim.helpers';

test.use({ serviceWorkers: 'block' });

const LOAD = { timeout: 20_000 };
/** Карточка с постером (замер QA 2026-11-19): объявление e8204967-…, card3 554×600, оригинал 738×1600 с чёрными полями. */
const POSTER = { title: 'מסעדה וגן אירועים', id: 'e8204967-0da2-4807-9f98-c1330c7e30b4', nat: [554, 600] as [number, number] };
/** Рамка окна при ширине экрана 375 (iPhone 13 Mini) — замер QA 2026-11-19. */
const FRAME_375 = { w: 341, h: 256 };
const RATIO_TOL = 0.02;
const SIZE_TOL = 2;
/** Порог 2.2: однотонные поля не больше 10 % высоты/ширины картинки. */
const MAX_MARGIN = 0.1;
/** Сколько картинок карточек проверяем в 2.2 (до ~60, без привязки к числу карточек на проде). */
const MAX_IMAGES = 60;

async function setup(page: Page) {
  await page.addInitScript(COOKIE_PWA_INIT);
  await prepare(page);
}

/** Прокручивать /search вниз, пока не найдётся `until` (или пока лента не перестанет расти). */
async function scrollSearch(page: Page, until?: Locator, maxRounds = 25) {
  let lastH = 0;
  let still = 0;
  for (let i = 0; i < maxRounds; i++) {
    if (until && (await until.count())) return true;
    const h = await page.evaluate(() => {
      window.scrollTo(0, document.documentElement.scrollHeight);
      return document.documentElement.scrollHeight;
    });
    await page.waitForTimeout(700);
    if (h === lastH) {
      if (++still >= 3) break;
    } else still = 0;
    lastH = h;
  }
  return until ? (await until.count()) > 0 : true;
}

test.describe('Обрезка однотонных полей картинки карточки (#494e0b)', () => {
  test.beforeEach(async ({ page }) => {
    await setup(page);
  });

  test('карточка с постером: card3 без чёрных полей, картинка целиком #494e0b @mobile @prod-safe', async ({ page }) => {
    await page.goto('/search');
    await expect(page.locator(MEDIA).first(), 'карточки на /search').toBeVisible(LOAD);

    // Заголовок карточки — лист-элемент с точным текстом; по нему не кликаем, карточка — ближайший предок со ссылкой и окном медиа.
    const title = page.getByText(POSTER.title, { exact: true }).first();
    const found = await scrollSearch(page, title);
    test.skip(!found, `карточки «${POSTER.title}» нет на /search — данные прода`);
    const card = title.locator(
      `xpath=ancestor::*[.//a[contains(@href,'businessdetail')] and .//*[contains(concat(' ', @class, ' '), ' aspect-[4/3] ')]][1]`,
    );
    const href = await card.locator('a[href*="businessdetail"]').first().getAttribute('href');
    test.info().annotations.push({ type: 'карточка', description: `${POSTER.title} → ${href}` });
    test.skip(!href?.includes(POSTER.id), `карточка «${POSTER.title}» ведёт не на ${POSTER.id} (${href}) — данные прода`);

    const media = card.locator(MEDIA).first();
    await media.scrollIntoViewIfNeeded();
    const img = media.locator('img:not(.opacity-0)').first();
    await expect
      .poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0), { ...LOAD, message: 'картинка карточки загрузилась' })
      .toBe(true);

    const m = await img.evaluate((el: HTMLImageElement) => {
      const w = el.closest('.aspect-\\[4\\/3\\]')!.getBoundingClientRect();
      const b = el.getBoundingClientRect();
      return {
        src: el.currentSrc || el.src,
        nat: [el.naturalWidth, el.naturalHeight] as [number, number],
        fit: getComputedStyle(el).objectFit,
        frame: [w.width, w.height] as [number, number],
        box: [b.width, b.height] as [number, number],
        vw: window.innerWidth,
      };
    });
    const size = `${m.frame[0].toFixed(1)}×${m.frame[1].toFixed(1)}`;
    test.info().annotations.push({ type: 'замер', description: `${short(m.src)} ${m.nat.join('×')}, fit ${m.fit}, рамка ${size}, экран ${m.vw}` });

    expect(m.src, 'файл с обрезанными полями ….card3.webp').toMatch(/\.card3\.webp(\?|$)/);
    expect(m.fit, 'object-fit окна').toBe('contain');
    const rCard = m.nat[0] / m.nat[1];
    const rExp = POSTER.nat[0] / POSTER.nat[1];
    expect(Math.abs(rCard - rExp) / rExp, `пропорция card3 ${m.nat.join('×')} ≈ ${POSTER.nat.join('×')} (±2 %)`).toBeLessThanOrEqual(RATIO_TOL);
    expect(Math.abs(m.frame[0] / m.frame[1] - 4 / 3) / (4 / 3), `рамка ${size} — 4:3`).toBeLessThanOrEqual(RATIO_TOL);
    expect(Math.abs(m.box[0] - m.frame[0]) + Math.abs(m.box[1] - m.frame[1]), 'img на всё окно (contain)').toBeLessThanOrEqual(2);
    if (m.vw === 375) {
      expect(Math.abs(m.frame[0] - FRAME_375.w), `ширина рамки ${size} ≈ ${FRAME_375.w}`).toBeLessThanOrEqual(SIZE_TOL);
      expect(Math.abs(m.frame[1] - FRAME_375.h), `высота рамки ${size} ≈ ${FRAME_375.h}`).toBeLessThanOrEqual(SIZE_TOL);
    }

    // Чёрные полосы в самом файле card3: ≤ 1 тёмной строки сверху и снизу.
    const card3 = await measureLines(page, m.src);
    const dk = darkEdges(card3);
    test.info().annotations.push({ type: 'card3', description: `тёмных строк сверху ${dk.top}, снизу ${dk.bottom}; столбцов слева ${dk.left}, справа ${dk.right}` });
    expect(dk.top, 'card3: тёмных строк сверху ≤ 1').toBeLessThanOrEqual(1);
    expect(dk.bottom, 'card3: тёмных строк снизу ≤ 1').toBeLessThanOrEqual(1);

    // Содержимое не обрезано: пропорция card3 = пропорции постера в оригинале (оригинал без его чёрных полей) ±2 %.
    const origUrl = m.src.replace(/\.card3\.webp(\?.*)?$/, '');
    const orig = await measureLines(page, origUrl);
    const od = darkEdges(orig);
    const rows = orig.rowMean.length;
    const cols = orig.colMean.length;
    const contentW = orig.w * (1 - (od.left + od.right) / cols);
    const contentH = orig.h * (1 - (od.top + od.bottom) / rows);
    const rPoster = contentW / contentH;
    test.info().annotations.push({
      type: 'оригинал',
      description: `${short(origUrl)} ${orig.w}×${orig.h}, чёрные поля (в замере ${cols}×${rows}): сверху ${od.top}, снизу ${od.bottom}, слева ${od.left}, справа ${od.right} → постер ≈ ${contentW.toFixed(0)}×${contentH.toFixed(0)}`,
    });
    expect(Math.abs(rCard - rPoster) / rPoster, `пропорция card3 ${rCard.toFixed(3)} = постеру в оригинале ${rPoster.toFixed(3)} (±2 %)`).toBeLessThanOrEqual(RATIO_TOL);
  });

  test('ни у одной картинки карточек нет однотонных полей >10% #494e0b @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(180_000);
    await page.goto('/search');
    await expect(page.locator(MEDIA).first(), 'карточки на /search').toBeVisible(LOAD);
    await scrollSearch(page);

    // Прокрутить каждое окно медиа в видимость (lazy), пока не наберётся до MAX_IMAGES загруженных картинок.
    const media = page.locator(MEDIA);
    const total = await media.count();
    const srcs: string[] = [];
    for (let i = 0; i < total && srcs.length < MAX_IMAGES; i++) {
      const mm = media.nth(i);
      if (!(await mm.isVisible())) continue; // скрытый слайд карусели
      if (await mm.locator('video').count()) continue;
      const img = mm.locator('img:not(.opacity-0)').first();
      if (!(await img.count())) continue;
      await mm.scrollIntoViewIfNeeded();
      const ok = await expect
        .poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0), { timeout: 10_000 })
        .toBe(true)
        .then(() => true, () => false);
      if (!ok) continue;
      const src = await img.evaluate((el: HTMLImageElement) => el.currentSrc || el.src);
      if (!srcs.includes(src)) srcs.push(src);
    }
    expect(srcs.length, '/search: загрузились картинки карточек').toBeGreaterThan(0);
    const card3 = srcs.filter((s) => /\.card3\.webp(\?|$)/.test(s));
    test.info().annotations.push({ type: 'выборка', description: `${srcs.length} картинок из ${total} окон медиа, из них .card3.webp — ${card3.length}` });
    expect(card3.length, 'есть хотя бы одна картинка .card3.webp').toBeGreaterThan(0);

    const bad: string[] = [];
    const failed: string[] = [];
    for (const src of srcs) {
      try {
        const l = await measureLines(page, src, undefined, 400);
        const u = uniformMargins(l);
        if (u.vFrac > MAX_MARGIN || u.hFrac > MAX_MARGIN) {
          bad.push(`${short(src)} ${l.w}×${l.h}: по высоте ${(u.vFrac * 100).toFixed(0)}% (↑${u.top} ↓${u.bottom}), по ширине ${(u.hFrac * 100).toFixed(0)}% (←${u.left} →${u.right}) из ${l.colMean.length}×${l.rowMean.length}`);
        }
      } catch (e) {
        failed.push(`${short(src)}: ${(e as Error).message.split('\n')[0]}`);
      }
    }
    if (failed.length) test.info().annotations.push({ type: 'не прочитались', description: failed.join('; ') });
    expect(failed.length, `картинки прочитались в canvas: ${failed.join('; ')}`).toBeLessThanOrEqual(Math.floor(srcs.length * 0.1));
    expect(bad, `картинки с однотонными полями > ${MAX_MARGIN * 100}% по высоте или ширине`).toEqual([]);
  });
});
